/bin/zsh -lc "python -c \"import pandas as pd,numpy as np; from scipy.special import expit; d=pd.read_csv('data/nls_ses_processed.csv'); X=np.c_[np.ones(len(d)),d.SES.to_numpy()]; y=d['BA DEGREE COMPLETED'].astype(float).to_numpy(); b=np.array([np.log(y.mean()/(1-y.mean())),0.]);
for i in range(100):
 p=expit(X@b); s=X.T@(y-p); I=X.T@((p*(1-p))[:,None]*X); step=np.linalg.solve(I,s); b+=step
 if i%10==0: print(i,b,np.max(abs(step)),np.max(abs(s)))
 if np.max(abs(step))<1e-12: break
print(b, np.sqrt(np.linalg.inv(I)[1,1]))\""

