/bin/zsh -lc "python -c \"import pandas as pd,numpy as np; from scipy.optimize import minimize; from scipy.special import expit; d=pd.read_csv('data/nls_ses_processed.csv'); print(d.isna().sum());
def fit(y,x):
 X=np.c_[np.ones(len(x)),x]; y=np.asarray(y,float); f=lambda b:(np.sum(np.logaddexp(0,X@b)-y*(X@b)), X.T@(expit(X@b)-y)); q=minimize(lambda b:f(b)[0],[ -3,0],jac=lambda b:f(b)[1],method='BFGS'); return q.x
for col in ['SES','PERCENTILE IN CLASS','ABILITY: COMPOSITE OF ASVAB SCORE','FAMILY SIZE OF SAMPLE']:
 print(col,fit(d['BA DEGREE COMPLETED'],d[col]))
print('y reverse',fit(~d['BA DEGREE COMPLETED'],d.SES))\""

